# Convoy effect: one long job first makes everyone wait (FCFS)
def avg_wait(bursts):
    t, total = 0, 0
    for b in bursts:          # all arrive at time 0, run in list order
        total += t            # this job waited for everything before it
        t += b
    return total / len(bursts)

long_first = [24, 3, 3]
print("order 24,3,3 -> waits 0,24,27 -> avg", avg_wait(long_first))
short_first = sorted(long_first)   # shortest job first
print("order", short_first, "-> avg", avg_wait(short_first))

# Same idea with time slicing: a 24-unit hog cannot block the short jobs
def rr_wait(bursts, q):
    rem, t, finish = list(bursts), 0, [0] * len(bursts)
    while any(rem):
        for i, r in enumerate(rem):
            if r:
                run = min(q, r); t += run; rem[i] -= run
                if not rem[i]: finish[i] = t
    return sum(f - b for f, b in zip(finish, bursts)) / len(bursts)

print("round robin q=4 on 24,3,3 -> avg wait", rr_wait(long_first, 4))

# Starvation in priority scheduling and how aging fixes it
HIGH = 3            # smaller number = more important; a new HIGH job arrives every tick
def first_run(aging, ticks=60):
    base, waited = 5, 0
    for t in range(ticks):
        # effective priority improves by 1 for every 10 ticks spent waiting
        eff = base - (waited // 10 if aging else 0)
        if eff < HIGH:            # now better than the constant stream of HIGH jobs
            return t, eff
        waited += 1
    return None

for aging in (False, True):
    r = first_run(aging)
    if r: print(f"aging={aging}: low job (priority 5) first runs at tick {r[0]}, effective priority {r[1]}")
    else: print(f"aging={aging}: low job (priority 5) still waiting after 60 ticks -> starved")

# CPU share from nice values (weight table: nice 0 = 1024, each step x1.25)
TABLE = {0: 1024, 5: 335}
def weight(nice):
    return TABLE[nice]

tasks = {"T1": 0, "T2": 5}
w = {n: weight(v) for n, v in tasks.items()}
total = sum(w.values())
period = 6.0   # ms scheduling period
print("nice values:", tasks, "weights:", w)
for n in tasks:
