    print(f"{n}: share {100 * share:.1f}%  slice {period * share:.2f} ms")
print("vruntime of T2 grows %.2fx faster per ms of CPU" % (1024 / w["T2"]))

# Priority inversion: L holds a lock, H wants it, M (no lock) preempts L
def simulate(inherit):
    prio = {"L": 1, "M": 2, "H": 3}
    arrive = {"L": 0, "M": 1, "H": 1}
    need = {"L": 4, "M": 5, "H": 1}      # ticks of CPU still needed
    lock_holder, order = "L", []         # L already owns the lock; H needs it
    t = 0
    while need["H"] > 0:
        ready = [n for n in need if need[n] > 0 and arrive[n] <= t]
        if "H" in ready and lock_holder == "L":
            ready.remove("H")            # H is blocked on the lock
        eff = dict(prio)
        if inherit and "H" in need and need["H"] > 0 and arrive["H"] <= t:
            eff["L"] = prio["H"]         # L inherits H's priority while H waits
        run = max(ready, key=lambda n: eff[n])
        need[run] -= 1; order.append(run); t += 1
        if run == "L" and need["L"] == 2:
            lock_holder = None           # L leaves its critical section
    return "".join(order)

for inherit in (False, True):
    s = simulate(inherit)
    print(f"inheritance={inherit}: schedule {s}, H finished at tick {len(s)}")
